begin;
-- Presentation only; no price, stock, invoice, commission or permission changes.
create table private.owner_pos_catalog_layouts(layout_id uuid primary key,branch_id uuid not null references public.business_branches(branch_id),version integer not null check(version>0),spec jsonb not null,reason text not null,actor_id uuid not null references auth.users(id),created_at timestamptz not null default clock_timestamp(),unique(branch_id,version));
create table private.owner_pos_layout_commands(request_id uuid primary key,actor_id uuid not null,payload jsonb not null,result jsonb not null,created_at timestamptz not null default clock_timestamp());
do $$declare t text;begin foreach t in array array['owner_pos_catalog_layouts','owner_pos_layout_commands']loop execute format('alter table private.%I enable row level security',t);execute format('revoke all on private.%I from public,anon,authenticated,service_role',t);execute format('create trigger immutable_pos_layout before update or delete on private.%I for each row execute function private.owner_tax_immutable()',t);end loop;end$$;
create function private.save_owner_pos_catalog_layout(p_request uuid,p_branch uuid,p_expected_version integer,p_spec jsonb,p_reason text)returns jsonb language plpgsql security definer set search_path=pg_catalog as $$
declare actor uuid;payload jsonb;prior private.owner_pos_layout_commands;latest private.owner_pos_catalog_layouts;result jsonb;id uuid:=gen_random_uuid();x jsonb;begin
 actor:=private.require_owner_tax_branch(p_branch);
 if p_request is null or p_expected_version is null or p_expected_version<0 or jsonb_typeof(p_spec)is distinct from'object'or(select count(*)from jsonb_object_keys(p_spec))<>2 or jsonb_typeof(p_spec->'categories')is distinct from'array'or jsonb_typeof(p_spec->'items')is distinct from'array'or length(trim(coalesce(p_reason,'')))not between 5 and 500 then raise exception 'Valid explicit catalogue layout required'using errcode='22023';end if;
 for x in select value from jsonb_array_elements(p_spec->'categories')loop
 if jsonb_typeof(x)is distinct from'object'or(select count(*)from jsonb_object_keys(x))<>5 or not(x?'category_id'and x?'name_ar'and x?'name_en'and x?'sort_order'and x?'enabled')or length(trim(coalesce(x->>'name_ar','')))not between 1 and 100 or length(trim(coalesce(x->>'name_en','')))not between 1 and 100 or jsonb_typeof(x->'enabled')is distinct from'boolean'or jsonb_typeof(x->'sort_order')is distinct from'number'or(x->>'sort_order')::numeric<0 or(x->>'sort_order')::numeric<>trunc((x->>'sort_order')::numeric)or(x->>'category_id')::uuid is null then raise exception 'Valid bilingual category required'using errcode='22023';end if;end loop;
 if(select count(distinct(c->>'category_id')::uuid)from jsonb_array_elements(p_spec->'categories')c)<>jsonb_array_length(p_spec->'categories')then raise exception 'Duplicate category'using errcode='22023';end if;
 for x in select value from jsonb_array_elements(p_spec->'items')loop
 if jsonb_typeof(x)is distinct from'object'or(select count(*)from jsonb_object_keys(x))<>4 or not(x?'item_id'and x?'category_id'and x?'sort_order'and x?'featured')or jsonb_typeof(x->'featured')is distinct from'boolean'or jsonb_typeof(x->'sort_order')is distinct from'number'or(x->>'sort_order')::numeric<0 or(x->>'sort_order')::numeric<>trunc((x->>'sort_order')::numeric)or not exists(select 1 from public.business_catalog_items c where c.item_id=(x->>'item_id')::uuid and c.branch_id=p_branch)or(x->>'category_id'is not null and not exists(select 1 from jsonb_array_elements(p_spec->'categories')c where(c->>'category_id')::uuid=(x->>'category_id')::uuid))then raise exception 'Valid branch item and category required'using errcode='22023';end if;end loop;
 if(select count(distinct(i->>'item_id')::uuid)from jsonb_array_elements(p_spec->'items')i)<>jsonb_array_length(p_spec->'items')then raise exception 'Duplicate item layout'using errcode='22023';end if;
 payload:=jsonb_build_object('branch',p_branch,'version',p_expected_version,'spec',p_spec,'reason',trim(p_reason));
 perform pg_advisory_xact_lock(hashtextextended('owner-pos-layout-request:'||p_request,0));select *into prior from private.owner_pos_layout_commands where request_id=p_request;
 if found then if prior.actor_id<>actor or prior.payload<>payload then raise exception 'Request payload mismatch'using errcode='22023';end if;return prior.result;end if;
 perform pg_advisory_xact_lock(hashtextextended('owner-pos-layout:'||p_branch,0));select *into latest from private.owner_pos_catalog_layouts where branch_id=p_branch order by version desc limit 1;
 if coalesce(latest.version,0)<>p_expected_version then raise exception 'Catalogue layout version changed'using errcode='40001';end if;
 insert into private.owner_pos_catalog_layouts values(id,p_branch,p_expected_version+1,p_spec,trim(p_reason),actor,clock_timestamp());result:=jsonb_build_object('layout_id',id,'version',p_expected_version+1,'presentation_only',true);
 insert into private.owner_pos_layout_commands values(p_request,actor,payload,result,clock_timestamp());
 insert into public.business_audit_log(actor,actor_id,action,entity,entity_id,branch_id,before_data,after_data)values(actor::text,actor,'owner_pos_catalog_layout_saved','pos_catalog_layout',p_branch::text,p_branch,to_jsonb(latest),payload||result);return result;end$$;
create function private.get_owner_pos_catalog_layout(p_branch uuid default null,p_after uuid default null)returns jsonb language plpgsql security definer set search_path=pg_catalog as $$declare b uuid;layout private.owner_pos_catalog_layouts;items jsonb;begin
 if not coalesce(private.has_live_invoice_session(),false)or private.active_staff_role()is distinct from'owner'then raise exception 'Current owner session required'using errcode='42501';end if;
 b:=p_branch;if b is null then select branch_id into b from public.business_branches where is_default and is_active;end if;perform private.require_owner_tax_branch(b);
 select *into layout from private.owner_pos_catalog_layouts where branch_id=b order by version desc limit 1;
 select coalesce(jsonb_agg(to_jsonb(x)order by item_id),'[]')into items from(select item_id,name,name_en,item_type from public.business_catalog_items where branch_id=b and is_active and(p_after is null or item_id>p_after)order by item_id limit 101)x;
 return jsonb_build_object('branch',b,'version',coalesce(layout.version,0),'spec',coalesce(layout.spec,'{"categories":[],"items":[]}'::jsonb),'items',case when jsonb_array_length(items)>100 then items-100 else items end,'has_more',jsonb_array_length(items)>100);end$$;
create function public.save_owner_pos_catalog_layout(p_request uuid,p_branch uuid,p_expected_version integer,p_spec jsonb,p_reason text)returns jsonb language sql security invoker set search_path=pg_catalog as $$select private.save_owner_pos_catalog_layout(p_request,p_branch,p_expected_version,p_spec,p_reason)$$;
create function public.get_owner_pos_catalog_layout(p_branch uuid default null,p_after uuid default null)returns jsonb language sql security invoker set search_path=pg_catalog as $$select private.get_owner_pos_catalog_layout(p_branch,p_after)$$;
revoke all on function private.save_owner_pos_catalog_layout(uuid,uuid,integer,jsonb,text),public.save_owner_pos_catalog_layout(uuid,uuid,integer,jsonb,text),private.get_owner_pos_catalog_layout(uuid,uuid),public.get_owner_pos_catalog_layout(uuid,uuid)from public,anon,authenticated,service_role;
grant execute on function private.save_owner_pos_catalog_layout(uuid,uuid,integer,jsonb,text),public.save_owner_pos_catalog_layout(uuid,uuid,integer,jsonb,text),private.get_owner_pos_catalog_layout(uuid,uuid),public.get_owner_pos_catalog_layout(uuid,uuid)to authenticated;
notify pgrst,'reload schema';commit;
